SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, RANK() OVER w_recent shipping_fee_rank, DENSE_RANK() OVER (PARTITION BY customer_id, status ORDER BY amount DESC) amount_dense_rank, AVG(shipping_fee) OVER (PARTITION BY status ORDER BY order_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) shipping_fee_avg_3_prior, PERCENT_RANK() OVER (PARTITION BY channel ORDER BY amount DESC) amount_percent_rank, CORR(amount, discount) OVER (PARTITION BY store_id) corr_amount_discount FROM orders WINDOW w_recent AS (PARTITION BY status ORDER BY shipping_fee NULLS LAST);
